/**
 * Apply pending migrations in ./drizzle.
 *   npm run db:migrate              → local PGlite (.data/pglite)
 *   npm run db:migrate -- --prod    → production Neon (reads .env.production.local)
 * Migrations are additive SQL generated by drizzle-kit and tracked in
 * drizzle.__drizzle_migrations, so re-running is safe.
 */
import { config } from 'dotenv';

const prod = process.argv.includes('--prod');
if (prod) {
  config({ path: '.env.production.local' });
  if (!process.env.DATABASE_URL_UNPOOLED && !process.env.DATABASE_URL) throw new Error('No production DATABASE_URL. Run: vercel env pull .env.production.local --environment=production');
  const { neon } = await import('@neondatabase/serverless');
  const { drizzle } = await import('drizzle-orm/neon-http');
  const { migrate } = await import('drizzle-orm/neon-http/migrator');
  const db = drizzle(neon(process.env.DATABASE_URL_UNPOOLED ?? process.env.DATABASE_URL));
  await migrate(db, { migrationsFolder: './drizzle' });
  console.log('✓ Production migrations applied');
} else {
  const { PGlite } = await import('@electric-sql/pglite');
  const { drizzle } = await import('drizzle-orm/pglite');
  const { migrate } = await import('drizzle-orm/pglite/migrator');
  const dir = process.env.PGLITE_DIR ?? '.data/pglite';
  (await import('node:fs')).mkdirSync(dir, { recursive: true });
  const client = new PGlite(dir);
  await migrate(drizzle(client), { migrationsFolder: './drizzle' });
  await client.close();
  console.log('✓ Local migrations applied');
}
